KG42.register("edges-fd6cc65a18eeffc08fda18bb",{"id":"S-6c25260703114d68","source":"KG40-404d7eddbf0fc37c","type":"links","target":"COMP-ffbf050cce03a2e6","evidence_class":"S","scientific_acceptance":false,"relation_scope":"original_occurrence_pair_only","internal_to_parent":false,"paper_ids":["25-p2p_ancillary_bidding"],"assertions":[{"id":"25-p2p_ancillary_bidding::v141-c-R006::E::v141-c-R006-E001","paper":"25-p2p_ancillary_bidding","rule_id":"v141-c-R006","rule_ref":"25-p2p_ancillary_bidding::v141-c-R006","record":{"edge_id":"v141-c-R006-E001","source":"coordination.local_operator","target":"matching.counterparties","type":"links","constraint_ids":["v141-c-R006-C003"],"evidence_ids":["v141-b-g01-E05","v141-b-g01-E07"]},"evidence_class":"S","provenance_gate":"direct_C_edge_with_constraint_and_source_excerpt","scientific_acceptance":false,"accepted_constraint_ids":["v141-c-R006-C003"],"held_constraint_ids":[],"semantic_review_status":"supported","source":"KG40-404d7eddbf0fc37c","target":"COMP-ffbf050cce03a2e6","source_occurrence_id":"25-p2p_ancillary_bidding::v141-c-R006::V::coordination.local_operator","target_occurrence_id":"25-p2p_ancillary_bidding::v141-c-R006::V::matching.counterparties","source_unit_id":"25-p2p_ancillary_bidding::v141-a-M01-p2p-cda::coordination.local_operator","target_unit_id":"25-p2p_ancillary_bidding::v141-a-M01-p2p-cda::matching.counterparties","omega":{"market_type":"LEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"matching","context_text":"Candidate buyer bids and seller asks considered in the corresponding community CDA order book. | Counterparty matching in the community CDA during its Agreement Period, within the corresponding time-slot order book. | Counterparty matching within each time-slot order book of the community CDA. | The exchange coordinating P2P energy trading within the community, for each corresponding CDA order book.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-E05","v141-b-g01-E06","v141-b-g01-E07","v141-b-g01-E10","v141-b-g01-E11"]},"active":true,"source_signature":"00c144ed1bc62b5165a5d9e0d6119cdd3809934da8fd3f786f4be09e6a4de46c","relation_scope":"original_occurrence_pair_only","internal_to_parent":false,"source_science":{"mechanism_id":"v141-a-M01-p2p-cda","source_definition":"Demand bids arrive asynchronously at the community exchange. Scope: P2P community exchange during the CDA Agreement Period, for time slots in Target Time Period T. Supply asks arrive asynchronously at the community exchange. Scope: P2P community exchange during the CDA Agreement Period, for time slots in Target Time Period T.","target_definition":"The counterparty-matching process is triggered whenever a newly submitted demand bid arrives at the exchange. Scope: Counterparty matching in the community CDA during its Agreement Period, within the corresponding time-slot order book. Condition: Arrival of a new buyer bid; this is an alternative trigger to arrival of a new seller ask. The counterparty-matching process is triggered whenever a newly submitted supply ask arrives at the exchange. Scope: Counterparty matching in the community CDA during its Agreement Period, within the corresponding time-slot order book. Condition: Arrival of a new seller ask; this is an alternative trigger to arrival of a new buyer bid. The community exchange performs counterparty matching by attempting to match the bids and asks in the order book. Scope: The exchange coordinating P2P energy trading within the community, for each corresponding CDA order book. Condition: A bid or ask arrives and is placed in the corresponding order book. The CDA matches the candidate buyer and seller when the bid price is at least the ask price, establishing their P2P trading agreement for the matched electricity. Scope: Candidate buyer bids and seller asks considered in the corresponding community CDA order book. Condition: The candidate bid and ask satisfy π_{b,t} ≥ π_{s,t}. Matching proceeds from the top to the bottom of the order book and stops when no further match can be made. Bids rank by descending bid price and asks by ascending ask price; among equal-priced orders, later arrivals rank lower. Scope: Counterparty matching within each time-slot order book of the community CDA.","constraints":[{"constraint_id":"v141-c-R006-C003","kind":"procedural","role":"core","statement":"The community exchange performs counterparty matching by attempting to match the bids and asks in the order book. Scope: The exchange coordinating P2P energy trading within the community, for each corresponding CDA order book. Condition: A bid or ask arrives and is placed in the corresponding order book.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["coordination.local_operator","matching.counterparties"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g01-E05","v141-b-g01-E07"]}],"evidence":[{"evidence_id":"v141-b-g01-E05","location":{"location_id":"src-212077b9a1-p04-c1r2__v141-a-M01-bidding","page":4,"printed_page":null,"section":null,"anchor_text":"Fig. 2. The timeline for ancillary service provision As presented in Section 2, customers trade ener","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"definition"},"source_text":"A bid, which is submitted by a buyer, is represented by o_{b,t}(b_t, π_{b,t}, σ_{b,t}, τ_{b,t}), which means that the buyer b_t would like to by the σ_{b,t} (kWh) amount of electricity at the price π_{b,t} (£/kWh), and the bid arrives at the ‘exchange’ at the time τ_{b,t}. Note that the exchange is a centralized or decentralized platform set for P2P energy trading within the community. Similarly, an ask, which is submitted by a seller is represented by o_{s,t}(s_t, π_{s,t}, σ_{s,t}, τ_{s,t})."},{"evidence_id":"v141-b-g01-E07","location":{"location_id":"src-212077b9a1-p04-c1r3__v141-a-M01-matching","page":4,"printed_page":null,"section":null,"anchor_text":"peach time slot t in the Target Time Period T, there is one order book. In seeach order book, the bi","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"condition"},"source_text":"Every time a bid/ask arrives at the exchange, it will be allocated in the corresponding order book based on the above-described principles, and then the exchange will try to match the bids and asks in the order book. If the following relationship is satisfied for a bid o_{b,t} and an ask o_{s,t}: π_{b,t} ≥ π_{s,t}, (1) then the following amount of electricity will be matched: σ_{matched,t} = min(σ_{b,t}, σ_{s,t}) (2)"}],"omega":{"market_type":"LEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"matching","context_text":"Candidate buyer bids and seller asks considered in the corresponding community CDA order book. | Counterparty matching in the community CDA during its Agreement Period, within the corresponding time-slot order book. | Counterparty matching within each time-slot order book of the community CDA. | The exchange coordinating P2P energy trading within the community, for each corresponding CDA order book.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-E05","v141-b-g01-E06","v141-b-g01-E07","v141-b-g01-E10","v141-b-g01-E11"]},"source_record":{"edge_id":"v141-c-R006-E001","source":"coordination.local_operator","target":"matching.counterparties","type":"links","constraint_ids":["v141-c-R006-C003"],"evidence_ids":["v141-b-g01-E05","v141-b-g01-E07"]},"paper_scope_note":"CDA, ancillary services, and residual agreement adjustment are kept separate; arrival events, matched orders, and the next ZIP update are not variables at the same time point; reward and compensation costs are different settlement sub-items."}}],"assertion_ids":["25-p2p_ancillary_bidding::v141-c-R006::E::v141-c-R006-E001"]});
